describe('User Profile Update Confirmation', () => {
  beforeEach(() => {
    cy.visit('/profile');
    cy.login('testuser@example.com', 'password123');
  });

  it('should display confirmation message after successfully updating profile', () => {
    cy.get('[data-testid="profile-form"]').should('be.visible');

    cy.get('[data-testid="first-name-input"]').clear().type('John');
    cy.get('[data-testid="last-name-input"]').clear().type('Doe');
    cy.get('[data-testid="email-input"]').clear().type('john.doe@example.com');

    cy.get('[data-testid="save-profile-button"]').click();

    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .and('contain', 'Profile updated successfully');

    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success-alert');
  });

  it('should display error message when updating profile with invalid email', () => {
    cy.get('[data-testid="profile-form"]').should('be.visible');

    cy.get('[data-testid="first-name-input"]').clear().type('Jane');
    cy.get('[data-testid="email-input"]').clear().type('invalid-email');

    cy.get('[data-testid="save-profile-button"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Please enter a valid email address');

    cy.get('[data-testid="confirmation-message"]').should('not.exist');
  });

  it('should dismiss confirmation message when close button is clicked', () => {
    cy.get('[data-testid="first-name-input"]').clear().type('Alice');
    cy.get('[data-testid="save-profile-button"]').click();

    cy.get('[data-testid="confirmation-message"]').should('be.visible');

    cy.get('[data-testid="close-confirmation-button"]').click();

    cy.get('[data-testid="confirmation-message"]').should('not.be.visible');
  });

  it('should auto-dismiss confirmation message after 5 seconds', () => {
    cy.get('[data-testid="first-name-input"]').clear().type('Bob');
    cy.get('[data-testid="save-profile-button"]').click();

    cy.get('[data-testid="confirmation-message"]').should('be.visible');

    cy.wait(5000);

    cy.get('[data-testid="confirmation-message"]').should('not.be.visible');
  });
});
